import React, { useEffect, useMemo, useState } from 'react';
import {
  Box,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  Divider,
  IconButton,
  InputAdornment,
  Slide,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import { TransitionProps } from '@mui/material/transitions';
import PersonOutlineIcon from '@mui/icons-material/PersonOutline';
import PhoneAndroidIcon from '@mui/icons-material/PhoneAndroid';
import BadgeOutlinedIcon from '@mui/icons-material/BadgeOutlined';
import CalendarMonthOutlinedIcon from '@mui/icons-material/CalendarMonthOutlined';
import SearchRoundedIcon from '@mui/icons-material/SearchRounded';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import CheckCircleOutlineIcon from '@mui/icons-material/CheckCircleOutline';
import { useAppDispatch } from '../../../store/hooks';
import { useSelector } from 'react-redux';
import { addCustomer as selectCustomer } from '../store/BasketSelector';
import { addCustomerDetailes } from '../store/BasketSlice';
import { HEADER_GRADIENT } from '../../../theme/appColors';
import { useGetCustomerByMobileQuery } from '../../posApi';
import { ICustomerMobileDatails } from '../../../core/Interface/customer.interface';
import { useNotifier } from '../../../core/Notifier';

/* ── tokens ──────────────────────────────────────────────────────────────── */
const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';

/* ── slide-up transition ─────────────────────────────────────────────────── */
const SlideUp = React.forwardRef(function SlideUp(
  props: TransitionProps & { children: React.ReactElement<string, string> },
  ref: React.Ref<unknown>
) {
  return (
    <Slide
      direction="up"
      ref={ref}
      {...props}
    />
  );
});

/* ── shared field label ──────────────────────────────────────────────────── */
const FieldLabel: React.FC<{ icon: React.ReactNode; text: string }> = ({
  icon,
  text,
}) => (
  <Box
    sx={{
      alignItems: 'center',
      display: 'flex',
      gap: 0.75,
      mb: 0.75,
    }}
  >
    <Box sx={{ color: TEAL, display: 'flex', fontSize: 16 }}>{icon}</Box>
    <Typography
      sx={{
        color: '#374151',
        fontSize: 12,
        fontWeight: 700,
        letterSpacing: '0.04em',
        textTransform: 'uppercase',
      }}
    >
      {text}
    </Typography>
  </Box>
);

/* ── shared text-field sx ────────────────────────────────────────────────── */
const inputSx = {
  '& .MuiOutlinedInput-root': {
    '& fieldset': { borderColor: alpha(NAVY, 0.14) },
    '&.Mui-focused fieldset': { borderColor: TEAL, borderWidth: '1.5px' },
    '&:hover fieldset': { borderColor: alpha(TEAL, 0.5) },
    backgroundColor: '#fff',
    borderRadius: '10px',
  },
};

/* ── props ───────────────────────────────────────────────────────────────── */
interface OrderCustomerModalProps {
  open: boolean;
  onClose: () => void;
  /** Pre-fill delivery date (ISO string) */
  defaultDeliveryDate?: string;
}

/* ── component ───────────────────────────────────────────────────────────── */
const OrderCustomerModal: React.FC<OrderCustomerModalProps> = ({
  open,
  onClose,
  defaultDeliveryDate,
}) => {
  const dispatch   = useAppDispatch();
  const existing   = useSelector(selectCustomer);
  const { showErrorMessage } = useNotifier();
  const today = new Date().toISOString().split('T')[0];

  /* ── form state ─────────────────────────────────────────────────────── */
  const [mobile,       setMobile]       = useState(existing.mobile   ?? '');
  const [customerName, setCustomerName] = useState(existing.customerName ?? '');
  const [deliveryDate, setDeliveryDate] = useState(
    defaultDeliveryDate
      ? defaultDeliveryDate.split('T')[0]
      : existing.deliveryDateTime
        ? existing.deliveryDateTime.split('T')[0]
        : today
  );
  const [queryMobile,  setQueryMobile]  = useState('');
  const [touched,      setTouched]      = useState(false);

  /* reset when modal opens with existing data */
  useEffect(() => {
    if (open) {
      setMobile(existing.mobile ?? '');
      setCustomerName(existing.customerName ?? '');
      setDeliveryDate(
        defaultDeliveryDate
          ? defaultDeliveryDate.split('T')[0]
          : existing.deliveryDateTime
            ? existing.deliveryDateTime.split('T')[0]
            : today
      );
      setQueryMobile('');
      setTouched(false);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  /* ── customer lookup ────────────────────────────────────────────────── */
  const { data: lookupData, isFetching } = useGetCustomerByMobileQuery(
    queryMobile,
    { skip: queryMobile.length < 6 }
  );

  const suggestions: ICustomerMobileDatails[] = useMemo(() => {
    if (!lookupData) return [];
    return (
      (lookupData.data as { customers: ICustomerMobileDatails[] })
        ?.customers ?? []
    );
  }, [lookupData]);

  /* auto-fill name when exact match found */
  useEffect(() => {
    if (!queryMobile) return;
    const match = suggestions.find((s) => s.mobile === mobile);
    if (match) setCustomerName(match.name);
  }, [suggestions, mobile, queryMobile]);

  /* ── validation ─────────────────────────────────────────────────────── */
  const isValidMobile = (v: string) =>
    v.startsWith('0') ? /^[0-9]{10}$/.test(v) : /^[1-9]{9}$/.test(v);

  const mobileError = touched && !isValidMobile(mobile);
  const canSave     = isValidMobile(mobile) && customerName.trim() && deliveryDate;

  /* ── handlers ───────────────────────────────────────────────────────── */
  const handleMobileChange = (v: string) => {
    if (v.length > 10) return;
    setMobile(v);
    if (v.length >= 6) setQueryMobile(v);
    const match = suggestions.find((s) => s.mobile === v);
    if (match) setCustomerName(match.name);
    else if (v !== mobile) setCustomerName('');
  };

  const handleSearch = () => {
    if (mobile.length >= 6) setQueryMobile(mobile);
  };

  const handleSuggestionSelect = (s: ICustomerMobileDatails) => {
    setMobile(s.mobile);
    setCustomerName(s.name);
    setQueryMobile('');
  };

  const handleSave = () => {
    if (!isValidMobile(mobile)) {
      setTouched(true);
      showErrorMessage('Please enter a valid mobile number.');
      return;
    }
    dispatch(
      addCustomerDetailes({
        mobile,
        customerName: customerName.trim(),
        deliveryDateTime: deliveryDate,
      })
    );
    onClose();
  };

  const handleClose = () => {
    onClose();
  };

  /* ── whether to show suggestion list ────────────────────────────────── */
  const showSuggestions = queryMobile.length >= 6 && suggestions.length > 0;

  return (
    <Dialog
      PaperProps={{
        sx: {
          borderRadius: '16px',
          boxShadow: '0 30px 80px rgba(15,23,42,0.25)',
          overflow: 'hidden',
          width: { xs: '100%', sm: 460 },
        },
      }}
      TransitionComponent={SlideUp}
      fullWidth
      maxWidth={false}
      onClose={handleClose}
      open={open}
    >
      {/* ── Header ────────────────────────────────────────────────── */}
      <Box
        sx={{
          background: HEADER_GRADIENT,
          px: 3,
          py: 2.5,
          position: 'relative',
        }}
      >
        <IconButton
          onClick={handleClose}
          size="small"
          sx={{
            '&:hover': { background: 'rgba(255,255,255,0.15)' },
            color: 'rgba(255,255,255,0.7)',
            position: 'absolute',
            right: 12,
            top: 12,
          }}
        >
          <CloseRoundedIcon sx={{ fontSize: 18 }} />
        </IconButton>

        <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5 }}>
          <Box
            sx={{
              alignItems: 'center',
              background: 'rgba(255,255,255,0.15)',
              borderRadius: '10px',
              display: 'flex',
              height: 42,
              justifyContent: 'center',
              width: 42,
            }}
          >
            <PersonOutlineIcon sx={{ color: '#fff', fontSize: 22 }} />
          </Box>
          <Box>
            <Typography
              sx={{
                color: '#fff',
                fontSize: 17,
                fontWeight: 800,
                lineHeight: 1.2,
              }}
            >
              {existing.mobile ? 'Update Customer' : 'Add Customer'}
            </Typography>
            <Typography
              sx={{ color: 'rgba(255,255,255,0.65)', fontSize: 12 }}
            >
              Enter customer details for this order
            </Typography>
          </Box>
        </Box>
      </Box>

      {/* ── Form ──────────────────────────────────────────────────── */}
      <DialogContent
        sx={{
          background: '#F8FAFC',
          px: 3,
          py: 3,
        }}
      >
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2.5 }}>

          {/* Mobile number */}
          <Box>
            <FieldLabel
              icon={<PhoneAndroidIcon fontSize="inherit" />}
              text="Mobile Number"
            />
            <Box sx={{ display: 'flex', gap: 1 }}>
              <TextField
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      {isFetching ? (
                        <CircularProgress size={14} sx={{ color: TEAL }} />
                      ) : (
                        <PhoneAndroidIcon
                          sx={{ color: alpha(NAVY, 0.35), fontSize: 17 }}
                        />
                      )}
                    </InputAdornment>
                  ),
                }}
                autoComplete="off"
                autoFocus
                error={mobileError}
                fullWidth
                helperText={
                  mobileError
                    ? 'Enter a valid 9 or 10-digit mobile number'
                    : undefined
                }
                inputProps={{ maxLength: 10, inputMode: 'numeric' }}
                onBlur={() => setTouched(true)}
                onChange={(e) =>
                  handleMobileChange(e.target.value.replace(/\D/g, ''))
                }
                onKeyDown={(e) => {
                  if (e.key === 'Enter') handleSearch();
                }}
                placeholder="e.g. 0771234567"
                size="small"
                sx={inputSx}
                value={mobile}
              />
              <Button
                onClick={handleSearch}
                sx={{
                  '&:hover': { background: alpha(TEAL, 0.12) },
                  borderColor: alpha(TEAL, 0.4),
                  borderRadius: '10px',
                  color: TEAL,
                  flexShrink: 0,
                  fontWeight: 600,
                  px: 2,
                  textTransform: 'none',
                }}
                variant="outlined"
              >
                <SearchRoundedIcon sx={{ fontSize: 18 }} />
              </Button>
            </Box>

            {/* Suggestion list */}
            {showSuggestions && (
              <Box
                sx={{
                  background: '#fff',
                  border: `1px solid ${alpha(TEAL, 0.25)}`,
                  borderRadius: '10px',
                  boxShadow: '0 8px 24px rgba(0,0,0,0.08)',
                  mt: 0.75,
                  overflow: 'hidden',
                }}
              >
                {suggestions.map((s, i) => (
                  <React.Fragment key={s.mobile}>
                    {i > 0 && <Divider />}
                    <Box
                      onClick={() => handleSuggestionSelect(s)}
                      sx={{
                        '&:hover': { background: alpha(TEAL, 0.05) },
                        alignItems: 'center',
                        cursor: 'pointer',
                        display: 'flex',
                        justifyContent: 'space-between',
                        px: 2,
                        py: 1,
                        transition: 'background 0.12s',
                      }}
                    >
                      <Box>
                        <Typography
                          sx={{
                            color: NAVY,
                            fontSize: 13,
                            fontWeight: 700,
                          }}
                        >
                          {s.name}
                        </Typography>
                        <Typography
                          sx={{ color: '#64748B', fontSize: 12 }}
                        >
                          {s.mobile}
                        </Typography>
                      </Box>
                      <CheckCircleOutlineIcon
                        sx={{ color: TEAL, fontSize: 18, opacity: 0.7 }}
                      />
                    </Box>
                  </React.Fragment>
                ))}
              </Box>
            )}
          </Box>

          {/* Customer name */}
          <Box>
            <FieldLabel
              icon={<BadgeOutlinedIcon fontSize="inherit" />}
              text="Customer Name"
            />
            <TextField
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <BadgeOutlinedIcon
                      sx={{ color: alpha(NAVY, 0.35), fontSize: 17 }}
                    />
                  </InputAdornment>
                ),
              }}
              autoComplete="off"
              fullWidth
              onChange={(e) => setCustomerName(e.target.value)}
              placeholder="Full name"
              size="small"
              sx={inputSx}
              value={customerName}
            />
          </Box>

          {/* Delivery date */}
          <Box>
            <FieldLabel
              icon={<CalendarMonthOutlinedIcon fontSize="inherit" />}
              text="Delivery Date"
            />
            <TextField
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <CalendarMonthOutlinedIcon
                      sx={{ color: alpha(NAVY, 0.35), fontSize: 17 }}
                    />
                  </InputAdornment>
                ),
              }}
              fullWidth
              inputProps={{ min: today }}
              onChange={(e) => setDeliveryDate(e.target.value)}
              size="small"
              sx={inputSx}
              type="date"
              value={deliveryDate}
            />
          </Box>

        </Box>
      </DialogContent>

      {/* ── Footer ────────────────────────────────────────────────── */}
      <DialogActions
        sx={{
          background: '#F8FAFC',
          borderTop: '1px solid #E2E8F0',
          gap: 1.5,
          px: 3,
          py: 2,
        }}
      >
        <Button
          onClick={handleClose}
          sx={{
            borderColor: alpha(NAVY, 0.2),
            borderRadius: '10px',
            color: '#475569',
            fontWeight: 600,
            height: 42,
            px: 3,
            textTransform: 'none',
          }}
          variant="outlined"
        >
          Cancel
        </Button>
        <Button
          disabled={!canSave}
          onClick={handleSave}
          sx={{
            '&.Mui-disabled': {
              background: '#CBD5E1',
              color: '#94A3B8',
            },
            '&:hover': {
              background: `linear-gradient(135deg, #0c7a7c 0%, #0a6b6d 100%)`,
            },
            background: `linear-gradient(135deg, ${TEAL} 0%, #0c7a7c 100%)`,
            borderRadius: '10px',
            boxShadow: `0 4px 14px ${alpha(TEAL, 0.35)}`,
            color: '#fff',
            fontWeight: 700,
            height: 42,
            px: 3,
            textTransform: 'none',
          }}
          variant="contained"
        >
          {existing.mobile ? 'Update Customer' : 'Save Customer'}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default React.memo(OrderCustomerModal);
